using UnityEngine;
using UnityEngine.UI;
using TMPro;
using _Project.Scripts.Utility;

/// <summary>
/// Main menu: who you are, and the three ways into a game.
/// Layout is generated by Editor/MainMenuSetup — this script only handles state.
/// </summary>
public class MainMenuUI : MonoBehaviour
{
    [Header("Identity")]
    [SerializeField] private TMP_InputField nameInput;

    [Header("Entry Points")]
    [SerializeField] private Button quickPlayButton;
    [SerializeField] private Button createGameButton;
    [SerializeField] private Button joinGameButton;
    [SerializeField] private TMP_InputField codeInput;

    [Header("Chrome")]
    [SerializeField] private TMP_Text statusText;
    [SerializeField] private Button quitButton;

    private INetworkService _network;

    /// <summary>True while a join is in flight, so the menu cannot fire a second one.</summary>
    private bool _busy;

    private void Start()
    {
        ServiceLocator.TryGetService(out _network);

        if (nameInput != null)
        {
            nameInput.text = PlayerPrefs.GetString(Launcher.NicknameKey, string.Empty);
            nameInput.onEndEdit.AddListener(_ => CommitName());
        }

        if (codeInput != null)
        {
            codeInput.characterLimit = RoomCode.Length;
            codeInput.onValidateInput = ValidateCodeChar;
            codeInput.onValueChanged.AddListener(_ => UpdateInteractable());
        }

        if (quickPlayButton != null) quickPlayButton.onClick.AddListener(OnQuickPlay);
        if (createGameButton != null) createGameButton.onClick.AddListener(OnCreateGame);
        if (joinGameButton != null) joinGameButton.onClick.AddListener(OnJoinGame);
        if (quitButton != null) quitButton.onClick.AddListener(OnQuit);

        if (_network != null)
        {
            _network.OnConnectedToServer += OnConnected;
            _network.OnRoomJoinFailed += OnJoinFailed;

            // Coming back from a finished game we can still be sitting in the old room,
            // and nothing on this screen works until we are out of it.
            if (_network.IsInRoom) _network.LeaveRoom();
        }

        UpdateInteractable();
        RefreshIdleStatus();
    }

    private void OnDestroy()
    {
        if (_network != null)
        {
            _network.OnConnectedToServer -= OnConnected;
            _network.OnRoomJoinFailed -= OnJoinFailed;
        }
    }

    // ============================================
    // IDENTITY
    // ============================================

    /// <summary>
    /// The nickname travels with the join, so it has to be committed before any of the
    /// three entry points fire — a name typed but never confirmed would otherwise reach
    /// nobody, and the lobby would fill with default names.
    /// </summary>
    private void CommitName()
    {
        if (nameInput == null) return;

        string chosen = nameInput.text.Trim();

        if (string.IsNullOrEmpty(chosen))
        {
            // Never let the name go blank: fall back to whatever Launcher generated.
            chosen = PlayerPrefs.GetString(Launcher.NicknameKey, "Player");
            nameInput.text = chosen;
        }

        PlayerPrefs.SetString(Launcher.NicknameKey, chosen);
        PlayerPrefs.Save();
        _network?.SetPlayerName(chosen);
    }

    // ============================================
    // ENTRY POINTS
    // ============================================

    private void OnQuickPlay()
    {
        CommitName();
        BeginJoin("Looking for a game...");
        _network?.QuickPlay();
    }

    private void OnCreateGame()
    {
        CommitName();
        BeginJoin("Creating game...");

        // Private: a created game is for people you hand the code to, not for whoever
        // happens to press Quick Play at the same moment.
        _network?.CreateRoom(isPublic: false);
    }

    private void OnJoinGame()
    {
        string code = RoomCode.Normalize(codeInput != null ? codeInput.text : null);

        if (!RoomCode.IsValid(code))
        {
            SetStatus($"Enter a {RoomCode.Length}-letter code");
            return;
        }

        CommitName();
        BeginJoin($"Joining {code}...");
        _network?.JoinRoom(code);
    }

    private void OnQuit()
    {
#if UNITY_EDITOR
        UnityEditor.EditorApplication.isPlaying = false;
#else
        Application.Quit();
#endif
    }

    /// <summary>
    /// Success needs no handling here: NetworkService loads the lobby scene on join,
    /// so this screen simply stops existing.
    /// </summary>
    private void BeginJoin(string status)
    {
        _busy = true;
        UpdateInteractable();
        SetStatus(status);
    }

    // ============================================
    // STATE
    // ============================================

    private void OnConnected()
    {
        UpdateInteractable();
        RefreshIdleStatus();
    }

    private void OnJoinFailed(string reason)
    {
        _busy = false;
        UpdateInteractable();

        // Set last: UpdateInteractable does not touch the status line, so the reason
        // survives rather than being reset to "Ready".
        SetStatus(reason);
    }

    private void UpdateInteractable()
    {
        bool ready = _network != null && _network.IsConnected && !_busy;

        if (quickPlayButton != null) quickPlayButton.interactable = ready;
        if (createGameButton != null) createGameButton.interactable = ready;

        // Join stays dead until the code is actually complete - no point spending a
        // round trip to be told four letters were needed.
        if (joinGameButton != null)
            joinGameButton.interactable = ready && RoomCode.IsValid(codeInput != null ? codeInput.text : null);

        if (codeInput != null) codeInput.interactable = !_busy;
        if (nameInput != null) nameInput.interactable = !_busy;
    }

    private void RefreshIdleStatus()
    {
        if (_busy) return;
        SetStatus(_network != null && _network.IsConnected ? "Ready" : "Connecting...");
    }

    private char ValidateCodeChar(string text, int charIndex, char addedChar)
    {
        char upper = char.ToUpperInvariant(addedChar);

        // '\0' rejects the keystroke outright. I and O are not in the alphabet, so they
        // simply cannot be typed - better than accepting them and quietly joining a
        // different room than the one the player was told about.
        return RoomCode.IsInAlphabet(upper) ? upper : '\0';
    }

    private void SetStatus(string message)
    {
        if (statusText != null) statusText.text = message;
    }
}
